void reverseArray(int* arr, int size) {
    for (int i = 0; i < size / 2; ++i) {
        int tmp = arr[i];
        arr[i] = arr[size - 1 - i];
        arr[size - 1 - i] = tmp;
    }
}

void reverseArray(std::vector<int>& arr) {
    for (size_t i = 0; i < arr.size() / 2; ++i)
        std::swap(arr[i], arr[arr.size() - 1 - i]);
}

