int* makeArray(int size) {
    int* a = malloc(size * sizeof(int));
    if (a == NULL) return NULL;
    for (int i = 0; i < size; i++) a[i] = 0;
    return a;          // anroparen ansvarar för free(a)
}
// Alternativ: calloc(size, sizeof(int)) nollställer åt dig

void printAverages(const std::map<std::string, std::vector<int>>& m) {
    for (const auto& [name, values] : m) {
        if (values.empty()) continue;
        double sum = 0;
        for (int v : values) sum += v;
        std::cout << name << ": " << sum / values.size() << "\n";
    }
}
